metadata.er-schema:
{
  "title": "looply · 订单模块 实体关系图",
  "version": "v5.1 · 2026-06-24",
  "tables": [
    {
      "name": "checkout_session",
      "comment": "结算会话",
      "columns": [
        {
          "name": "id",
          "comment": "主键",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "user_id",
          "comment": "买家（→ user_account）",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "checkout_status",
          "comment": "状态",
          "constraint": ""
        },
        {
          "name": "address_id",
          "comment": "收货地址（如已选）",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "total_amount",
          "comment": "预估总金额",
          "constraint": ""
        },
        {
          "name": "currency_code",
          "comment": "币种（ISO 4217）",
          "constraint": ""
        },
        {
          "name": "shipping_method",
          "comment": "配送方式（如已选）",
          "constraint": ""
        },
        {
          "name": "shipping_fee",
          "comment": "运费金额（如已选）",
          "constraint": ""
        },
        {
          "name": "parent_order_id",
          "comment": "转化的父订单（→ parent_order）",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "recovery_token",
          "comment": "恢复链接令牌",
          "constraint": "UNIQUE"
        },
        {
          "name": "expired_at",
          "comment": "过期时间",
          "constraint": ""
        },
        {
          "name": "created_at",
          "comment": "创建时间",
          "constraint": ""
        },
        {
          "name": "updated_at",
          "comment": "更新时间",
          "constraint": ""
        }
      ],
      "note": "进入结算页创建，支付成功转化为订单，超时标记弃单"
    },
    {
      "name": "checkout_session_item",
      "comment": "结算会话商品",
      "columns": [
        {
          "name": "id",
          "comment": "主键",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "session_id",
          "comment": "所属会话（→ checkout_session）",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "listing_id",
          "comment": "渠道上架（→ listing）",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "unit_price",
          "comment": "单价（快照）",
          "constraint": ""
        },
        {
          "name": "currency_code",
          "comment": "币种",
          "constraint": ""
        }
      ],
      "note": "快照结算时的商品和价格，用于弃单恢复"
    },
    {
      "name": "parent_order",
      "comment": "父订单",
      "columns": [
        {
          "name": "id",
          "comment": "主键",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "parent_order_no",
          "comment": "买家订单号",
          "constraint": "UNIQUE"
        },
        {
          "name": "user_id",
          "comment": "买家（→ user_account）",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "total_amount",
          "comment": "订单总金额（含运费税费）",
          "constraint": ""
        },
        {
          "name": "currency_code",
          "comment": "币种（ISO 4217）",
          "constraint": ""
        },
        {
          "name": "payment_ref_no",
          "comment": "支付单号（→ 支付模块）",
          "constraint": ""
        },
        {
          "name": "created_at",
          "comment": "创建时间",
          "constraint": ""
        },
        {
          "name": "updated_at",
          "comment": "更新时间",
          "constraint": ""
        }
      ],
      "note": "买家一次下单的整体订单，按商家拆分为多个子订单"
    },
    {
      "name": "order",
      "comment": "订单",
      "columns": [
        {
          "name": "id",
          "comment": "主键",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "order_no",
          "comment": "订单号",
          "constraint": "UNIQUE"
        },
        {
          "name": "parent_order_id",
          "comment": "所属父订单（→ parent_order）",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "user_id",
          "comment": "买家（→ user_account）",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "merchant_id",
          "comment": "商家（→ merchants）",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "order_status",
          "comment": "订单状态",
          "constraint": ""
        },
        {
          "name": "fulfillment_status",
          "comment": "履约状态（发货维度聚合）",
          "constraint": ""
        },
        {
          "name": "refund_status",
          "comment": "退款状态（退款维度聚合）",
          "constraint": ""
        },
        {
          "name": "subtotal_amount",
          "comment": "商品小计",
          "constraint": ""
        },
        {
          "name": "shipping_fee",
          "comment": "运费",
          "constraint": ""
        },
        {
          "name": "tax_amount",
          "comment": "税费（按收货州税率）",
          "constraint": ""
        },
        {
          "name": "currency_code",
          "comment": "币种（ISO 4217）",
          "constraint": ""
        },
        {
          "name": "address_id",
          "comment": "收货地址ID（→ address.id UUID）",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "recipient_first_name",
          "comment": "收件人名（快照）",
          "constraint": ""
        },
        {
          "name": "recipient_last_name",
          "comment": "收件人姓（快照）",
          "constraint": ""
        },
        {
          "name": "recipient_name",
          "comment": "收件人全名（快照，冗余拼接）",
          "constraint": ""
        },
        {
          "name": "recipient_phone",
          "comment": "收件人电话（快照，含区号）",
          "constraint": ""
        },
        {
          "name": "shipping_address_line1",
          "comment": "地址行1（快照）",
          "constraint": ""
        },
        {
          "name": "shipping_address_line2",
          "comment": "地址行2（快照）",
          "constraint": ""
        },
        {
          "name": "shipping_city",
          "comment": "城市（快照）",
          "constraint": ""
        },
        {
          "name": "shipping_state_province",
          "comment": "州/省（快照）",
          "constraint": ""
        },
        {
          "name": "shipping_postal_code",
          "comment": "邮编（快照）",
          "constraint": ""
        },
        {
          "name": "shipping_country_code",
          "comment": "国家编码（快照）",
          "constraint": ""
        },
        {
          "name": "paid_at",
          "comment": "付款时间",
          "constraint": ""
        },
        {
          "name": "completed_at",
          "comment": "交易完成时间",
          "constraint": ""
        },
        {
          "name": "cancelled_at",
          "comment": "取消时间",
          "constraint": ""
        },
        {
          "name": "created_at",
          "comment": "创建时间",
          "constraint": ""
        },
        {
          "name": "updated_at",
          "comment": "更新时间",
          "constraint": ""
        }
      ],
      "note": "按商家维度拆分，每单关联一个商家一个买家"
    },
    {
      "name": "order_item",
      "comment": "订单商品",
      "columns": [
        {
          "name": "id",
          "comment": "主键",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "order_id",
          "comment": "所属订单（→ order）",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "product_id",
          "comment": "实物商品（→ product）",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "listing_id",
          "comment": "渠道上架（→ listing）",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "item_name",
          "comment": "商品名称（快照）",
          "constraint": ""
        },
        {
          "name": "item_image",
          "comment": "商品主图（快照）",
          "constraint": ""
        },
        {
          "name": "condition_grade",
          "comment": "成色等级（快照）",
          "constraint": ""
        },
        {
          "name": "quantity",
          "comment": "数量（二手默认1）",
          "constraint": ""
        },
        {
          "name": "unit_price",
          "comment": "成交单价（快照）",
          "constraint": ""
        },
        {
          "name": "item_total",
          "comment": "小计",
          "constraint": ""
        },
        {
          "name": "currency_code",
          "comment": "币种",
          "constraint": ""
        },
        {
          "name": "fulfillment_status",
          "comment": "发货状态",
          "constraint": ""
        },
        {
          "name": "refund_status",
          "comment": "退款状态",
          "constraint": ""
        }
      ],
      "note": "快照购买时的商品信息和价格，双维度状态（发货+退款）独立流转"
    },
    {
      "name": "order_package",
      "comment": "订单包裹",
      "columns": [
        {
          "name": "id",
          "comment": "主键",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "order_id",
          "comment": "所属订单（→ order）",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "tracking_no",
          "comment": "物流追踪号（→ shipments.tracking_no）",
          "constraint": ""
        },
        {
          "name": "package_status",
          "comment": "包裹状态",
          "constraint": ""
        },
        {
          "name": "shipped_at",
          "comment": "发货时间",
          "constraint": ""
        },
        {
          "name": "received_at",
          "comment": "签收时间",
          "constraint": ""
        },
        {
          "name": "created_at",
          "comment": "创建时间",
          "constraint": ""
        },
        {
          "name": "updated_at",
          "comment": "更新时间",
          "constraint": ""
        }
      ],
      "note": "物理包裹，通常1订单=1包裹，装不下时拆多包裹"
    },
    {
      "name": "refund",
      "comment": "退款单",
      "columns": [
        {
          "name": "id",
          "comment": "主键",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "refund_no",
          "comment": "退款单号",
          "constraint": "UNIQUE"
        },
        {
          "name": "order_id",
          "comment": "所属订单（→ order）",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "refund_type",
          "comment": "退款类型",
          "constraint": ""
        },
        {
          "name": "refund_reason",
          "comment": "退款原因",
          "constraint": ""
        },
        {
          "name": "refund_amount",
          "comment": "退款金额",
          "constraint": ""
        },
        {
          "name": "currency_code",
          "comment": "币种",
          "constraint": ""
        },
        {
          "name": "refund_status",
          "comment": "退款状态",
          "constraint": ""
        },
        {
          "name": "request_channel",
          "comment": "申请渠道",
          "constraint": ""
        },
        {
          "name": "operator_id",
          "comment": "处理人ID",
          "constraint": ""
        },
        {
          "name": "operator_type",
          "comment": "处理人类型",
          "constraint": ""
        },
        {
          "name": "operator_note",
          "comment": "处理备注",
          "constraint": ""
        },
        {
          "name": "requested_at",
          "comment": "申请时间",
          "constraint": ""
        },
        {
          "name": "completed_at",
          "comment": "完成时间",
          "constraint": ""
        },
        {
          "name": "created_at",
          "comment": "创建时间",
          "constraint": ""
        },
        {
          "name": "updated_at",
          "comment": "更新时间",
          "constraint": ""
        }
      ],
      "note": "前期仅发货前退款，买家邮件申请，运营后台代操作"
    },
    {
      "name": "refund_item",
      "comment": "退款商品明细",
      "columns": [
        {
          "name": "id",
          "comment": "主键",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "refund_id",
          "comment": "所属退款单（→ refund）",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "order_item_id",
          "comment": "订单商品（→ order_item）",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "quantity",
          "comment": "退款数量",
          "constraint": ""
        },
        {
          "name": "refund_amount",
          "comment": "退款金额",
          "constraint": ""
        }
      ],
      "note": "支持部分退款，退款粒度到单件商品"
    },
    {
      "name": "payment_order",
      "comment": "支付单",
      "columns": [
        {
          "name": "id",
          "comment": "主键",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "payment_no",
          "comment": "支付单号",
          "constraint": "UNIQUE"
        },
        {
          "name": "parent_order_id",
          "comment": "关联父订单（→ parent_order）",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "user_id",
          "comment": "买家（冗余，免 join）",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "channel",
          "comment": "支付渠道（paypal / stripe）",
          "constraint": ""
        },
        {
          "name": "payment_method",
          "comment": "支付方式（paypal_wallet / credit_card）",
          "constraint": ""
        },
        {
          "name": "amount",
          "comment": "支付金额",
          "constraint": ""
        },
        {
          "name": "currency_code",
          "comment": "币种（ISO 4217）",
          "constraint": ""
        },
        {
          "name": "status",
          "comment": "支付单状态",
          "constraint": ""
        },
        {
          "name": "paid_at",
          "comment": "支付成功时间",
          "constraint": ""
        },
        {
          "name": "expired_at",
          "comment": "支付超时时间",
          "constraint": ""
        },
        {
          "name": "created_at",
          "comment": "创建时间",
          "constraint": ""
        },
        {
          "name": "updated_at",
          "comment": "更新时间",
          "constraint": ""
        }
      ],
      "note": "一次结算对应一笔支付单，parent_order.payment_ref_no 引用 payment_no"
    },
    {
      "name": "payment_transaction",
      "comment": "支付流水",
      "columns": [
        {
          "name": "id",
          "comment": "主键",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "transaction_no",
          "comment": "内部流水号",
          "constraint": "UNIQUE"
        },
        {
          "name": "payment_id",
          "comment": "所属支付单（→ payment_order）",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "transaction_type",
          "comment": "交易类型（payment / refund）",
          "constraint": ""
        },
        {
          "name": "channel_transaction_id",
          "comment": "渠道交易号（对账匹配键）",
          "constraint": "UNIQUE"
        },
        {
          "name": "amount",
          "comment": "交易金额",
          "constraint": ""
        },
        {
          "name": "currency_code",
          "comment": "币种",
          "constraint": ""
        },
        {
          "name": "channel_fee",
          "comment": "渠道手续费",
          "constraint": ""
        },
        {
          "name": "channel_fee_currency",
          "comment": "手续费币种",
          "constraint": ""
        },
        {
          "name": "net_amount",
          "comment": "实收/实退金额",
          "constraint": ""
        },
        {
          "name": "status",
          "comment": "流水状态",
          "constraint": ""
        },
        {
          "name": "refund_id",
          "comment": "关联退款单（→ refund，退款时）",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "channel_raw_data",
          "comment": "渠道原始响应（JSON）",
          "constraint": ""
        },
        {
          "name": "reconciliation_status",
          "comment": "对账状态",
          "constraint": ""
        },
        {
          "name": "reconciled_at",
          "comment": "对账时间",
          "constraint": ""
        },
        {
          "name": "created_at",
          "comment": "创建时间",
          "constraint": ""
        },
        {
          "name": "updated_at",
          "comment": "更新时间",
          "constraint": ""
        }
      ],
      "note": "每笔资金流动（收款/退款）一条记录，对账最小粒度"
    },
    {
      "name": "user_account",
      "comment": "用户（外部）",
      "columns": [
        {
          "name": "id",
          "comment": "用户ID",
          "constraint": "PRIMARY KEY"
        }
      ],
      "note": "来自登录注册模块"
    },
    {
      "name": "merchants",
      "comment": "商家（外部）",
      "columns": [
        {
          "name": "id",
          "comment": "商家ID",
          "constraint": "PRIMARY KEY"
        }
      ],
      "note": "来自主数据模块，区分自营/三方"
    },
    {
      "name": "product",
      "comment": "实物商品（外部）",
      "columns": [
        {
          "name": "product_id",
          "comment": "商品ID",
          "constraint": "PRIMARY KEY"
        }
      ],
      "note": "来自商品模块，一物一件"
    },
    {
      "name": "listing",
      "comment": "渠道上架（外部）",
      "columns": [
        {
          "name": "listing_id",
          "comment": "上架ID",
          "constraint": "PRIMARY KEY"
        }
      ],
      "note": "来自商品模块，渠道定价"
    }
  ],
  "relations": [
    {
      "from": "checkout_session",
      "to": "checkout_session_item",
      "type": "1:N",
      "label": "包含商品",
      "color": "#388E3C",
      "penwidth": 1.4
    },
    {
      "from": "checkout_session",
      "to": "parent_order",
      "type": "1:1",
      "label": "转化为订单",
      "color": "#388E3C",
      "penwidth": 1.4,
      "style": "dashed"
    },
    {
      "from": "parent_order",
      "to": "order",
      "type": "1:N",
      "label": "按商家拆单",
      "color": "#1565C0",
      "penwidth": 1.8
    },
    {
      "from": "order",
      "to": "order_item",
      "type": "1:N",
      "label": "包含商品",
      "color": "#1565C0",
      "penwidth": 1.8
    },
    {
      "from": "order",
      "to": "order_package",
      "type": "1:N",
      "label": "发货包裹",
      "color": "#E8833A",
      "penwidth": 1.4
    },
    {
      "from": "order",
      "to": "refund",
      "type": "1:N",
      "label": "发起退款",
      "color": "#C0392B",
      "penwidth": 1.4
    },
    {
      "from": "refund",
      "to": "refund_item",
      "type": "1:N",
      "label": "包含商品",
      "color": "#C0392B",
      "penwidth": 1.4
    },
    {
      "from": "refund_item",
      "to": "order_item",
      "type": "N:1",
      "label": "关联订单商品",
      "color": "#C0392B",
      "penwidth": 1.0
    },
    {
      "from": "parent_order",
      "to": "payment_order",
      "type": "1:1",
      "label": "支付单",
      "color": "#5E35B1",
      "penwidth": 1.4
    },
    {
      "from": "payment_order",
      "to": "payment_transaction",
      "type": "1:N",
      "label": "资金流水",
      "color": "#5E35B1",
      "penwidth": 1.4
    },
    {
      "from": "refund",
      "to": "payment_transaction",
      "type": "1:1",
      "label": "退款流水",
      "color": "#5E35B1",
      "penwidth": 1.0,
      "style": "dashed"
    },
    {
      "from": "checkout_session",
      "to": "user_account",
      "type": "N:1",
      "label": "买家"
    },
    {
      "from": "checkout_session_item",
      "to": "listing",
      "type": "N:1",
      "label": "渠道上架"
    },
    {
      "from": "order",
      "to": "merchants",
      "type": "N:1",
      "label": "商家"
    },
    {
      "from": "order_item",
      "to": "product",
      "type": "N:1",
      "label": "实物商品"
    },
    {
      "from": "order_item",
      "to": "listing",
      "type": "N:1",
      "label": "渠道上架"
    }
  ],
  "design_rules": {
    "parent_order_split": "买家一次下单按商家拆单：1 parent_order → N order（每商家一单）。支付模块以 parent_order 为单位对接，payment_ref_no 引用支付模块单号",
    "order_status_enum": "order_status 枚举：paid(已付款) / shipped(已发货) / completed(交易完成) / cancelled(已取消)。订单在支付成功后创建，起始状态即 paid。无 pending_payment 状态，支付前由 checkout_session 承载。流转：paid → shipped → completed；paid → cancelled（发货前取消）。所有包裹签收即标记 completed，无独立签收状态",
    "fulfillment_status_enum": "fulfillment_status 枚举：unfulfilled(未发货) / partially_fulfilled(部分发货) / fulfilled(全部发货)。由 order_package 状态聚合而来，解决部分发货场景。首个包裹发出 → partially_fulfilled；全部包裹发出 → fulfilled",
    "order_refund_status_enum": "order.refund_status 枚举：none(无退款) / partial(部分退款) / full(全额退款)。由 refund 表聚合而来，解决部分退款场景。全额退款后 order_status 保持 completed 不变，通过 refund_status=full 体现",
    "item_fulfillment_status_enum": "order_item.fulfillment_status 枚举：pending(待发货) / shipped(已发货) / received(已签收)。与 order.fulfillment_status 独立——order 级聚合所有商品，item 级跟踪单个商品",
    "item_refund_status_enum": "order_item.refund_status 枚举：none(无退款) / refunding(退款中) / refunded(已退款)。与 order.refund_status 独立——order 级聚合所有商品，item 级跟踪单个商品",
    "package_status_enum": "package_status 枚举：pending(待发货) / shipped(已发货) / received(已签收)",
    "payment_ref_no_rule": "parent_order.payment_ref_no = payment_order.payment_no，是订单系统与支付系统的桥梁。parent_order 不设 payment_status，退款进度从 refund 表实时聚合",
    "payment_order_status_enum": "payment_order.status 枚举：pending(待支付) / succeeded(成功) / failed(失败) / closed(超时关闭)。用户跳转支付网关时创建(pending)，回调成功(succeeded)后创建 parent_order + order",
    "payment_transaction_type_enum": "transaction_type 枚举：payment(收款) / refund(退款)。每笔和支付渠道的资金流动记录一条，对账最小粒度",
    "payment_transaction_status_enum": "payment_transaction.status 枚举：pending(处理中) / succeeded(成功) / failed(失败)",
    "reconciliation_status_enum": "reconciliation_status 枚举：unreconciled(未对账) / reconciled(已对账) / discrepant(差异待处理)。对账流程：拉取渠道结算报告 → 按 channel_transaction_id 匹配 → 比对 amount/channel_fee/net_amount → 标记结果",
    "payment_refund_link": "退款资金流：order.refund 审批通过 → 调用支付渠道退款 API → 创建 payment_transaction(type=refund, refund_id=退款单ID) → 渠道返回新 channel_transaction_id → 后续对账时匹配",
    "refund_status_enum": "refund_status 枚举：pending(待处理) / processing(处理中) / completed(已完成) / rejected(已拒绝)",
    "refund_type_enum": "refund_type 枚举：pre_shipment(发货前退款)。后续扩展退货退款时新增类型",
    "request_channel_enum": "request_channel 枚举：email(邮件)。后续扩展自助申请时新增 app / web",
    "operator_type_enum": "operator_type 枚举：admin(运营人员) / system(系统自动)。参考库存模块 inventory_ledger 的操作人设计模式",
    "address_snapshot": "订单创建时快照收货地址（address_id UUID + 10 个快照字段）。字段命名对齐地址模块：address_line1/state_province/postal_code。recipient_first_name + last_name 拆分存储（报关需要），recipient_name 冗余拼接用于展示。地址模块后续更新不影响已有订单",
    "price_snapshot": "order_item 在创建时快照 listing_price 为 unit_price。listing 价格变动不影响已有订单",
    "condition_snapshot": "order_item 快照 product_inspection.grade 为 condition_grade",
    "package_boundary": "订单模块用 order_package 记录「发了几个包裹」，物流模块管「怎么发」（承运商/追踪/轨迹）。跨模块关联：order_no = shipments.business_order_no（按订单维度），tracking_no = shipments.tracking_no（按包裹维度）。物流模块是独立信息服务，不直接引用订单实体",
    "order_completion_rule": "订单完成判定：所有 order_package.package_status 为 received → order_status 直接标记 completed。签收即完成，无独立签收状态。多维度状态独立流转：order_status 管生命周期，fulfillment_status 管发货进度，refund_status 管退款进度",
    "status_dimension_design": "三维度状态设计：order_status（生命周期）+ fulfillment_status（发货维度）+ refund_status（退款维度），各自独立流转，不会状态爆炸。示例：部分发货 = order_status=paid + fulfillment_status=partially_fulfilled；已完成+部分退款 = order_status=completed + refund_status=partial",
    "refund_blocks_shipping": "退款审批通过后，order_item.refund_status 变为 refunding → 该商品不得发货（发货时校验 refund_status = none）",
    "package_simplification": "订单 = 履约作业单元（按商家拆单，未来按仓库再拆）。多包裹仅因物理尺寸约束，不做包裹-商品映射。买家视角只关心「订单有几个包裹，追踪号是什么」",
    "checkout_status_enum": "checkout_status 枚举：pending(待转化) / converted(已转化)。不设 expired 状态，过期通过 expired_at 字段判断：pending 且 expired_at < now() 即为弃单",
    "checkout_to_order_flow": "完整数据流：购物车 → 进入结算页创建 checkout_session(pending) + items 快照 → 填地址/确认商品 → 提交/去支付 → 支付成功 → checkout_session(converted) + 创建 parent_order + order + order_item",
    "checkout_abandonment": "弃单规则：checkout_session 超时未完成支付 → 标记 expired。恢复机制：recovery_token 生成唯一恢复链接，买家点击可回到结算页。恢复时需检查商品是否仍可购买（二手一物一件，可能已售出）",
    "cart_to_order_flow": "购物车到订单数据流：cart_item.listing_id → checkout_session_item（快照价格）→ 支付成功 → order_item（product_id + listing_id + 快照价格/成色/名称/图片）",
    "financial_model": "订单金额公式：order 实际收款 = subtotal_amount + shipping_fee + tax_amount。subtotal_amount = SUM(order_item.item_total)。parent_order.total_amount = SUM(各 order 的实际收款)。后续扩展优惠时：实际收款 = subtotal_amount + shipping_fee - discount_amount + tax_amount",
    "tax_rule": "tax_amount 按收货地址所在州的税率计算（美国各州税率不同）。税费计算在结算时由应用层完成，订单只记录结果",
    "currency_rule": "同一订单内所有金额使用相同 currency_code",
    "user_id_redundancy": "parent_order.user_id 和 order.user_id 均冗余存储买家ID，源头在 checkout_session.user_id，避免多层 join",
    "merchant_id_vs_seller_id": "商品模块用 seller_id 引用 merchants.id（卖方语境），订单模块用 merchant_id 引用同一实体（商家语境）。同一 FK 目标，不同业务语义"
  }
}
